package com.milano.quotation.logistics;

import com.milano.quotation.common.AppException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.JsonNodeFactory;
import tools.jackson.databind.json.JsonMapper;

import java.time.Instant;
import java.util.*;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class LogisticsServiceTest {
    private LogisticsProviderRepository providers;private LogisticsChannelRepository channels;private LogisticsVersionRepository versions;private LogisticsService service;private final Map<UUID,LogisticsProviderEntity> providerRows=new LinkedHashMap<>();private final Map<UUID,LogisticsChannelEntity> channelRows=new LinkedHashMap<>();private final Map<UUID,LogisticsVersionEntity> versionRows=new LinkedHashMap<>();
    @BeforeEach void setup(){providers=mock(LogisticsProviderRepository.class);channels=mock(LogisticsChannelRepository.class);versions=mock(LogisticsVersionRepository.class);var guard=mock(LogisticsDatasetGuard.class);when(guard.nextRuleId()).thenAnswer(call->channelRows.size()+1);service=new LogisticsService(providers,channels,versions,new LogisticsWorkbookService(JsonMapper.builder().build()),guard);when(versions.findByChannelIdAndSourceHash(any(),anyString())).thenAnswer(call->versionRows.values().stream().filter(v->v.channelId.equals(call.getArgument(0))&&v.sourceHash.equals(call.getArgument(1))).findFirst());when(providers.save(any())).thenAnswer(c->{var row=(LogisticsProviderEntity)c.getArgument(0);providerRows.put(row.id,row);return row;});when(providers.saveAndFlush(any())).thenAnswer(c->{var row=(LogisticsProviderEntity)c.getArgument(0);providerRows.put(row.id,row);return row;});when(channels.save(any())).thenAnswer(c->{var row=(LogisticsChannelEntity)c.getArgument(0);channelRows.put(row.id,row);return row;});when(channels.saveAndFlush(any())).thenAnswer(c->{var row=(LogisticsChannelEntity)c.getArgument(0);channelRows.put(row.id,row);return row;});when(versions.save(any())).thenAnswer(c->{var row=(LogisticsVersionEntity)c.getArgument(0);versionRows.put(row.id,row);return row;});when(providers.findById(any())).thenAnswer(c->Optional.ofNullable(providerRows.get(c.getArgument(0))));when(channels.findById(any())).thenAnswer(c->Optional.ofNullable(channelRows.get(c.getArgument(0))));when(versions.findById(any())).thenAnswer(c->Optional.ofNullable(versionRows.get(c.getArgument(0))));when(providers.existsById(any())).thenAnswer(c->providerRows.containsKey(c.getArgument(0)));when(channels.existsById(any())).thenAnswer(c->channelRows.containsKey(c.getArgument(0)));when(providers.findAllByOrderByUpdatedAtDesc()).thenAnswer(c->new ArrayList<>(providerRows.values()));when(channels.findAllByOrderByUpdatedAtDesc()).thenAnswer(c->new ArrayList<>(channelRows.values()));when(channels.findByProviderIdOrderByUpdatedAtDesc(any())).thenAnswer(c->channelRows.values().stream().filter(v->v.providerId.equals(c.getArgument(0))).toList());when(versions.findAllByOrderByCreatedAtDesc()).thenAnswer(c->new ArrayList<>(versionRows.values()));when(channels.findAll()).thenAnswer(c->new ArrayList<>(channelRows.values()));when(versions.findByChannelIdOrderByVersionNumberDesc(any())).thenAnswer(c->versionRows.values().stream().filter(v->v.channelId.equals(c.getArgument(0))).toList());when(channels.countByProviderId(any())).thenAnswer(c->channelRows.values().stream().filter(v->v.providerId.equals(c.getArgument(0))).count());doAnswer(c->{versionRows.remove(((LogisticsVersionEntity)c.getArgument(0)).id);return null;}).when(versions).delete(any());doAnswer(c->{channelRows.remove(((LogisticsChannelEntity)c.getArgument(0)).id);return null;}).when(channels).delete(any());doAnswer(c->{channelRows.remove((UUID)c.getArgument(0));return null;}).when(channels).deleteById(any());doAnswer(c->{providerRows.remove(((LogisticsProviderEntity)c.getArgument(0)).id);return null;}).when(providers).delete(any());doAnswer(c->{providerRows.remove((UUID)c.getArgument(0));return null;}).when(providers).deleteById(any());}
    @Test void addsProviderAndChannelAndReturnsWorkspace(){var provider=service.addProvider(JsonNodeFactory.instance.objectNode().put("name","云途").put("code","yt"));var providerId=UUID.fromString(provider.path("id").asText());var channel=service.addChannel(JsonNodeFactory.instance.objectNode().put("providerId",providerId.toString()).put("name","云途普货").put("code","yt-ph"));assertEquals("YT",provider.path("code").asText());assertEquals("YT-PH",channel.path("code").asText());assertEquals(1,service.workspace().providers().size());assertEquals(1,service.workspace().channels().size());}
    @Test void validatesProviderAndChannelConflicts(){assertThrows(AppException.class,()->service.addProvider(JsonNodeFactory.instance.objectNode().put("name","").put("code","X")));when(providers.existsByCodeIgnoreCase("YT")).thenReturn(true);assertThrows(AppException.class,()->service.addProvider(JsonNodeFactory.instance.objectNode().put("name","云途").put("code","YT")));assertThrows(AppException.class,()->service.addChannel(JsonNodeFactory.instance.objectNode().put("providerId",UUID.randomUUID().toString()).put("name","渠道").put("code","C")));}
    @Test void updatesEnablesClonesAndDeletesChannelsWithOptimisticLock(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");channel.version=2;assertThrows(AppException.class,()->service.updateChannel(channel.id,JsonNodeFactory.instance.objectNode().put("code","C").put("name","新名称"),1));var updated=service.updateChannel(channel.id,JsonNodeFactory.instance.objectNode().put("code","C").put("name","新名称").put("enabled",false),2);assertEquals("新名称",updated.path("name").asText());assertThrows(AppException.class,()->service.setChannelEnabled(channel.id,true,1));assertTrue(service.setChannelEnabled(channel.id,true,2).path("enabled").asBoolean());service.deleteChannel(channel.id);verify(channels).delete(channel);}
    @Test void blocksDeleteAndCreatesValidatedManualDraft(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");var published=version(channel,"published","HASH1",rows());channel.currentVersionId=published.id;assertThrows(AppException.class,()->service.deleteChannel(channel.id));var invalid=JsonNodeFactory.instance.objectNode();invalid.putArray("rows").addObject().put("areaName","美国").put("weightFromKg",2).put("weightToKg",1);assertThrows(AppException.class,()->service.createManualDraft(channel.id,invalid));var body=JsonNodeFactory.instance.objectNode();body.set("rows",rows());var draft=service.createManualDraft(channel.id,body);assertEquals("draft",draft.path("status").asText());assertEquals(2,draft.path("versionNumber").asInt());}
    @Test void onlyDeletesEmptyProvidersAndUsesOptimisticLockForStatus(){var empty=provider("EMPTY","空物流商");empty.version=2;assertThrows(AppException.class,()->service.setProviderEnabled(empty.id,false,1));assertFalse(service.setProviderEnabled(empty.id,false,2).path("enabled").asBoolean());service.deleteProvider(empty.id);assertFalse(providerRows.containsKey(empty.id));var populated=provider("FULL","有渠道物流商");channel(populated,"FULL-C","渠道");assertThrows(AppException.class,()->service.deleteProvider(populated.id));assertTrue(providerRows.containsKey(populated.id));}
    @Test void publishesAndRollsBackWithAllGuards(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");var draft=version(channel,"draft","HASH1",rows());assertThrows(AppException.class,()->service.publish(channel.id,draft.id,"","ADMIN",true));((tools.jackson.databind.node.ObjectNode)draft.payload).put("errors",1);assertThrows(AppException.class,()->service.publish(channel.id,draft.id,"审核","ADMIN",true));((tools.jackson.databind.node.ObjectNode)draft.payload).put("errors",0).putObject("summary").put("removed",1);assertThrows(AppException.class,()->service.publish(channel.id,draft.id,"审核","ADMIN",false));var published=service.publish(channel.id,draft.id,"审核通过","ADMIN",true);assertEquals("published",published.path("status").asText());assertEquals(draft.id,channel.currentVersionId);var rolled=service.rollback(channel.id,draft.id,"回滚测试","ADMIN");assertEquals("published",rolled.path("status").asText());assertEquals(2,rolled.path("versionNumber").asInt());}
    @Test void requiresRemovalConfirmationWhenWeightCoverageShrinks(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");var published=version(channel,"published","BASE",rows());channel.currentVersionId=published.id;var draft=version(channel,"draft","SHRINK",rows());((tools.jackson.databind.node.ObjectNode)draft.payload).putObject("summary").put("removed",0).put("coverageReduced",1).put("highRisk",0);assertThrows(AppException.class,()->service.publishReviewed(channel.id,draft.id,"审核","ADMIN",false,false));assertEquals("published",service.publishReviewed(channel.id,draft.id,"审核","ADMIN",true,false).path("status").asText());}
    @Test void matchesProviderFilesAndProposesStableNewChannel(){var provider=provider("RONGDING","容鼎");var channel=channel(provider,"SUMAO-ABC123","容鼎美国纯商派DDP专线-敏货");var byName=service.matchProviderFile(provider.id,"容鼎美国纯商派DDP专线-敏货-价格更新.xlsx","a".repeat(64));assertEquals(channel.id.toString(),byName.path("channelId").asText());assertEquals("name",byName.path("matchType").asText());var byCode=service.matchProviderFile(provider.id,"SUMAO-ABC123-V3.xlsx","b".repeat(64));assertEquals("code",byCode.path("matchType").asText());var created=service.matchProviderFile(provider.id,"容鼎全新渠道.xlsx","c".repeat(64));assertEquals("create",created.path("action").asText());assertEquals("AUTO-RONGDING-CCCCCCCCCCCC",created.path("channelCode").asText());}
    @Test void globallyMatchesExactlyOneEnabledProviderByTwoEffectiveCharacters(){var yanwen=provider("YANWEN","燕文");assertEquals(yanwen.id.toString(),service.matchGlobalProvider(" 燕文-化妆品.xlsx").path("providerId").asText());assertEquals("unmatched",service.matchGlobalProvider("顺速宝专线.xlsx").path("providerMatchStatus").asText());var second=provider("YANWEN-2","燕文国际");assertEquals("ambiguous",service.matchGlobalProvider("燕文服装.xlsx").path("providerMatchStatus").asText());providerRows.remove(second.id);((tools.jackson.databind.node.ObjectNode)yanwen.payload).put("enabled",false);assertEquals("disabled",service.matchGlobalProvider("燕文服装.xlsx").path("providerMatchStatus").asText());}
    @Test void archivesVersionedChannelRejectsDraftAndRestoresSameIdentityOnImport(){var provider=provider("YANWEN","燕文");var channel=channel(provider,"YW-COS","燕文化妆品");channel.version=3;var published=version(channel,"published","PUBLISHED",rows());channel.currentVersionId=published.id;var draft=version(channel,"draft","DRAFT",rows());var archived=service.archiveChannel(channel.id,"渠道下线","ADMIN",3);assertTrue(archived.path("archived").asBoolean());assertEquals(1,archived.path("rejectedDrafts").asInt());assertEquals("rejected",draft.status);assertThrows(AppException.class,()->service.archiveChannel(channel.id,"重复","ADMIN",3));var match=service.matchProviderFile(provider.id,"燕文化妆品.xlsx","NEW-HASH");assertEquals("restore",match.path("action").asText());var items=JsonNodeFactory.instance.arrayNode();var item=items.addObject().put("providerId",provider.id.toString()).put("channelId",channel.id.toString()).put("channelName","燕文化妆品").put("channelCode",channel.code).put("fileName","燕文化妆品.xlsx").put("sourceHash","NEW-HASH").put("errors",0);item.set("rows",rows());item.putArray("issues");item.putArray("diffRows");item.putObject("summary").put("added",0).put("price",0).put("rule",0).put("removed",0).put("unchanged",1).put("highRisk",0);var result=service.importGlobalBatch(items,"ADMIN",false);assertEquals("restored-draft",result.path("items").get(0).path("action").asText());assertFalse(channel.archivedAt!=null);assertEquals(3,result.path("items").get(0).path("versionNumber").asInt());}
    @Test void requiresExplicitDraftReplacementAndKeepsRejectedHistory(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");var first=version(channel,"draft","HASH1",rows());var body=JsonNodeFactory.instance.objectNode().put("sourceHash","HASH2").put("fileName","next.xlsx").put("importedBy","ADMIN");body.set("rows",rows());assertThrows(AppException.class,()->service.createDraft(channel.id,body));var next=service.createDraftReplacing(channel.id,body,"替换测试");assertEquals("rejected",first.status);assertEquals("替换测试",first.payload.path("auditNote").asText());assertEquals(2,next.path("versionNumber").asInt());assertThrows(AppException.class,()->service.rejectDraft(channel.id,first.id,"再次终止","ADMIN"));}
    @Test void importsAndPublishesProviderBatchAtomicallyWithRiskConfirmation(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");var old=version(channel,"published","BASE",rows());channel.currentVersionId=old.id;var items=JsonNodeFactory.instance.arrayNode();var item=items.addObject().put("channelId",channel.id.toString()).put("channelName",channel.payload.path("name").asText()).put("channelCode",channel.code).put("fileName","渠道.xlsx").put("sourceHash","HASH-BATCH").put("errors",0);var raised=rows();((tools.jackson.databind.node.ObjectNode)raised.get(0)).put("pricePerKg",66);item.set("rows",raised);item.putArray("issues");item.putArray("diffRows");item.putObject("summary").put("added",0).put("price",1).put("rule",0).put("removed",0).put("unchanged",0).put("highRisk",1);var imported=service.importProviderBatch(provider.id,items,"ADMIN",false);assertEquals(1,imported.path("count").asInt());var versionId=UUID.fromString(imported.path("items").get(0).path("versionId").asText());var selections=JsonNodeFactory.instance.arrayNode();selections.addObject().put("channelId",channel.id.toString()).put("versionId",versionId.toString()).put("removalConfirmed",false).put("reviewConfirmed",false);assertThrows(AppException.class,()->service.publishProviderBatch(provider.id,selections,"批量审核","ADMIN"));selections.get(0).deepCopy();((tools.jackson.databind.node.ObjectNode)selections.get(0)).put("reviewConfirmed",true);var published=service.publishProviderBatch(provider.id,selections,"批量审核","ADMIN");assertEquals(1,published.path("count").asInt());assertEquals(versionId,channel.currentVersionId);var compact=published.path("published").get(0);assertEquals(versionId.toString(),compact.path("id").asText());assertEquals(channel.id.toString(),compact.path("channelId").asText());assertFalse(compact.has("rows"));assertFalse(compact.has("diffRows"));}
    @Test void importsMultipleDistinctNewChannelsInOneProviderBatch(){var provider=provider("P","物流商");var items=JsonNodeFactory.instance.arrayNode();for(int i=1;i<=2;i++){var item=items.addObject().put("channelId","").put("channelName","新渠道"+i).put("channelCode","NEW-"+i).put("fileName","新渠道"+i+".xlsx").put("sourceHash","HASH-NEW-"+i).put("errors",0);item.set("rows",rows());item.putArray("issues");item.putArray("diffRows");item.putObject("summary").put("added",1).put("price",0).put("rule",0).put("removed",0).put("unchanged",0).put("highRisk",0);}var imported=service.importProviderBatch(provider.id,items,"ADMIN",false);assertEquals(2,imported.path("count").asInt());assertEquals(2,channelRows.size());assertEquals(2,versionRows.size());}
    @Test void rejectsMixedBatchWithBlockingDraftBeforePublishingAnyVersion(){var provider=provider("P","物流商");var validChannel=channel(provider,"VALID","正常渠道");var blockedChannel=channel(provider,"BLOCKED","阻断渠道");var valid=version(validChannel,"draft","VALID-HASH",rows());var blocked=version(blockedChannel,"draft","BLOCKED-HASH",rows());((tools.jackson.databind.node.ObjectNode)blocked.payload).put("errors",2);var selections=JsonNodeFactory.instance.arrayNode();selections.addObject().put("channelId",validChannel.id.toString()).put("versionId",valid.id.toString()).put("removalConfirmed",false).put("reviewConfirmed",true);selections.addObject().put("channelId",blockedChannel.id.toString()).put("versionId",blocked.id.toString()).put("removalConfirmed",false).put("reviewConfirmed",true);assertThrows(AppException.class,()->service.publishProviderBatch(provider.id,selections,"批量审核","ADMIN"));assertEquals("draft",valid.status);assertEquals("draft",blocked.status);assertNull(validChannel.currentVersionId);assertNull(blockedChannel.currentVersionId);}
    @Test void rejectsInvalidEmptyConflictingAndStaleBatchSelections(){var provider=provider("P","物流商");assertThrows(AppException.class,()->service.importProviderBatch(UUID.randomUUID(),JsonNodeFactory.instance.arrayNode(),"ADMIN",false));assertThrows(AppException.class,()->service.importProviderBatch(provider.id,JsonNodeFactory.instance.arrayNode(),"ADMIN",false));assertThrows(AppException.class,()->service.importGlobalBatch(JsonNodeFactory.instance.arrayNode(),"ADMIN",false));var invalidProvider=JsonNodeFactory.instance.arrayNode();invalidProvider.addObject().put("providerId","not-a-uuid");assertThrows(AppException.class,()->service.importGlobalBatch(invalidProvider,"ADMIN",false));var blocked=JsonNodeFactory.instance.arrayNode();blocked.addObject().put("fileName","坏文件.xlsx").put("errors",1);assertThrows(AppException.class,()->service.importProviderBatch(provider.id,blocked,"ADMIN",false));var duplicate=JsonNodeFactory.instance.arrayNode();duplicate.addObject().put("channelId","").put("channelCode","SAME").put("errors",0);duplicate.addObject().put("channelId","").put("channelCode","SAME").put("errors",0);assertThrows(AppException.class,()->service.importProviderBatch(provider.id,duplicate,"ADMIN",false));var other=provider("OTHER","其他物流商");var foreign=channel(other,"FOREIGN","外部渠道");var cross=JsonNodeFactory.instance.arrayNode();cross.addObject().put("channelId",foreign.id.toString()).put("channelCode",foreign.code).put("sourceHash","NEW").put("errors",0);assertThrows(AppException.class,()->service.importProviderBatch(provider.id,cross,"ADMIN",false));var local=channel(provider,"LOCAL","本地渠道");version(local,"draft","OLD",rows());var stale=JsonNodeFactory.instance.arrayNode();stale.addObject().put("channelId",local.id.toString()).put("channelCode",local.code).put("sourceHash","NEW").put("errors",0);assertThrows(AppException.class,()->service.importProviderBatch(provider.id,stale,"ADMIN",false));}
    @Test void repairsLegacyDraftSummaryAgainstCurrentPublishedVersion(){var provider=provider("P","物流商");var channel=channel(provider,"C","渠道");var published=version(channel,"published","HASH-OLD",rows());channel.currentVersionId=published.id;var changed=rows();((tools.jackson.databind.node.ObjectNode)changed.get(0)).put("pricePerKg",66);var draft=version(channel,"draft","HASH-NEW",changed);((tools.jackson.databind.node.ObjectNode)draft.payload).putArray("diffRows");((tools.jackson.databind.node.ObjectNode)draft.payload).putObject("summary").put("price",0);service.workspace();assertEquals(0,draft.payload.path("summary").path("price").asInt());service.recompare(channel.id,draft.id);assertEquals(1,draft.payload.path("summary").path("price").asInt());assertEquals("price",draft.payload.path("diffRows").get(0).path("type").asText());}
    @Test void repairsFirstImportDraftAsAddedWithoutInventingRemovals(){var provider=provider("P","物流商");var channel=channel(provider,"C","首次渠道");var draft=version(channel,"draft","HASH-FIRST",rows());((tools.jackson.databind.node.ObjectNode)draft.payload).putArray("diffRows");((tools.jackson.databind.node.ObjectNode)draft.payload).putObject("summary").put("added",0).put("removed",5);service.recompare(channel.id,draft.id);assertEquals(1,draft.payload.path("summary").path("added").asInt());assertEquals(0,draft.payload.path("summary").path("removed").asInt());assertEquals("added",draft.payload.path("diffRows").get(0).path("type").asText());}
    @Test void blocksStalePublishedBaselineUntilRecompared(){
        var p=provider("P","物流商");var c=channel(p,"C","渠道");var first=version(c,"published","FIRST",rows());c.currentVersionId=first.id;
        var draft=version(c,"draft","DRAFT",rows());var concurrent=version(c,"published","CONCURRENT",rows());c.currentVersionId=concurrent.id;
        assertThrows(AppException.class,()->service.publishReviewed(c.id,draft.id,"QA","ADMIN",true,true));
        assertEquals("draft",draft.status);service.recompare(c.id,draft.id);
        assertEquals("published",service.publishReviewed(c.id,draft.id,"QA","ADMIN",true,true).path("status").asText());
    }
    @Test void oldManualEndpointCannotRemoveOriginalParserSafetyGate(){
        var p=provider("P","物流商");var c=channel(p,"C","渠道");var first=version(c,"published","FIRST",rows());c.currentVersionId=first.id;
        ((tools.jackson.databind.node.ObjectNode)first.payload).put("parserVersion","source-v1").put("quoteReady",false);
        var body=JsonNodeFactory.instance.objectNode().put("sourceHash","manual");body.set("rows",rows());
        assertThrows(AppException.class,()->service.createDraft(c.id,body));
    }
    private LogisticsProviderEntity provider(String code,String name){var row=new LogisticsProviderEntity();row.id=UUID.randomUUID();row.code=code;row.createdAt=Instant.now();row.updatedAt=row.createdAt;row.payload=JsonNodeFactory.instance.objectNode().put("id",row.id.toString()).put("code",code).put("name",name).put("enabled",true);providerRows.put(row.id,row);when(providers.findByCodeIgnoreCase(code)).thenReturn(Optional.of(row));return row;}
    private LogisticsChannelEntity channel(LogisticsProviderEntity provider,String code,String name){var row=new LogisticsChannelEntity();row.id=UUID.randomUUID();row.providerId=provider.id;row.code=code;row.ruleId=channelRows.size()+1;row.createdAt=Instant.now();row.updatedAt=row.createdAt;row.payload=JsonNodeFactory.instance.objectNode().put("id",row.id.toString()).put("providerId",provider.id.toString()).put("code",code).put("name",name).put("enabled",true).put("currentVersionId","");channelRows.put(row.id,row);when(channels.findByCodeIgnoreCase(code)).thenReturn(Optional.of(row));return row;}
    private LogisticsVersionEntity version(LogisticsChannelEntity channel,String status,String hash,tools.jackson.databind.node.ArrayNode rows){var row=new LogisticsVersionEntity();row.id=UUID.randomUUID();row.channelId=channel.id;row.versionNumber=(int)versionRows.values().stream().filter(v->v.channelId.equals(channel.id)).count()+1;row.status=status;row.sourceHash=hash;row.createdAt=Instant.now();row.payload=JsonNodeFactory.instance.objectNode().put("id",row.id.toString()).put("channelId",channel.id.toString()).put("versionNumber",row.versionNumber).put("status",status).put("sourceHash",hash).put("fileName","source.xlsx").put("errors",0).put("basePublishedVersionId",channel.currentVersionId==null?"":channel.currentVersionId.toString()).set("rows",rows);((tools.jackson.databind.node.ObjectNode)row.payload).putObject("summary").put("removed",0);versionRows.put(row.id,row);when(versions.findByChannelIdAndSourceHash(channel.id,hash)).thenReturn(Optional.of(row));return row;}
    private tools.jackson.databind.node.ArrayNode rows(){var rows=JsonNodeFactory.instance.arrayNode();rows.addObject().put("areaName","美国").put("countryCode","US").put("weightFromKg",0).put("weightToKg",2).put("pricePerKg",55);return rows;}
}
